def find_copies(g, stamp, noise, bg=0):
    H,W=len(g),len(g[0]); h=max(r for r,c in stamp)+1; w=max(c for r,c in stamp)+1
    out=[]
    for r in range(H-h+1):
        for c in range(W-w+1):
            cells=set((r+i,c+j) for i,j in stamp)
            ok=True
            for (a,b) in cells:
                if g[a][b]!=bg: ok=False; break
                for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                    n=(a+da,b+db)
                    if 0<=n[0]<H and 0<=n[1]<W:
                        if n not in cells and g[n[0]][n[1]]!=noise: ok=False; break
                if not ok: break
            if ok: out.append((r,c))
    return out
