from collections import deque
def components(g, val):
    H,W=len(g),len(g[0]); seen=set(); comps=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]==val and (r,c) not in seen:
                q=deque([(r,c)]); seen.add((r,c)); comp=[]
                while q:
                    a,b=q.popleft(); comp.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        n=(a+da,b+db)
                        if 0<=n[0]<H and 0<=n[1]<W and g[n[0]][n[1]]==val and n not in seen:
                            seen.add(n); q.append(n)
                comps.append(comp)
    return comps
def norm(cells):
    rs=[r for r,c in cells]; cs=[c for r,c in cells]
    r0,c0=min(rs),min(cs)
    return tuple(sorted((r-r0,c-c0) for r,c in cells)), (min(rs),min(cs),max(rs)-min(rs)+1,max(cs)-min(cs)+1)
def canon(stampcells):
    h=max(r for r,c in stampcells)+1; w=max(c for r,c in stampcells)+1
    return tuple(sorted(stampcells)),h,w
