def ring_noise(g, r, c, h, w, noise):
    H,W=len(g),len(g[0]); tot=0; nz=0
    for rr in range(max(0,r-1), min(H, r+h+1)):
        for cc in range(max(0,c-1), min(W, c+w+1)):
            if r<=rr<r+h and c<=cc<c+w: continue
            tot+=1; nz+= (g[rr][cc]==noise)
    return nz/max(tot,1)
